// sw.js: saves the whole app (page, model, runtime) on the phone at first visit,
// then serves it from the phone, so the app works in airplane mode.
// Generated by make_app.py. VERSION changes automatically whenever any file changes,
// which makes phones download the new model on their next visit with internet.
const VERSION = "8590db477e51";
const PREFIX = "fieldvision-78ff27-";
const CACHE = PREFIX + VERSION;
const FILES = [
  "./",
  "./advice.json",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./index.html",
  "./labels.json",
  "./manifest.json",
  "./model.onnx",
  "./predict.js",
  "./test.html",
  "./vendor/ort-wasm-simd-threaded.mjs",
  "./vendor/ort-wasm-simd-threaded.wasm",
  "./vendor/ort.wasm.min.js"
];

self.addEventListener("install", event => {
  event.waitUntil(
    caches.open(CACHE)
      .then(cache => cache.addAll(FILES))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(
        keys.filter(k => k.startsWith(PREFIX) && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", event => {
  if (event.request.method !== "GET") return;
  event.respondWith(
    caches.match(event.request, { ignoreSearch: true }).then(hit =>
      hit || fetch(event.request).catch(() =>
        event.request.mode === "navigate" ? caches.match("./index.html") : Response.error()))
  );
});
